// "What's new": short notes about each update, newest first. Add one when you ship something students
// (or owners) would notice. Ids are "date-NN" and only ever grow, so "seen up to this id" works.
export type NewsItem = { id: string; date: string; kind: "New" | "Improved" | "Fixed" | "Changed"; title: string; body: string; owners?: boolean };

export const NEWS: NewsItem[] = [
  { id: "2026-11-22-13", date: "2026-11-22", kind: "Changed", title: "Easier tailoring, cleaner menus", body: "Tailor for an opening now has one card to pick from: search every opening that fits, or take one of your top 3 matches, and it folds to one line once you pick. Interview shows practice questions for your best matches right away. About and Privacy & terms are full-width reading pages with a contents list. The menu under your name is shorter, and owners get the view switch, dashboard and light or dark right in the side bar.", owners: true },
  { id: "2026-11-22-11", date: "2026-11-22", kind: "New", title: "Texts for urgent deadlines", body: "Turn on texts in Account \u2192 Appearance & alerts and add your number: Remy texts you when an application closes today or tomorrow, at most once a day. Texts are in test mode for now, so they show on the owners\u2019 dashboard instead of your phone.", owners: true },
  { id: "2026-11-22-09", date: "2026-11-22", kind: "New", title: "Remy emails you when something fits", body: "When Remy finds a new opening that fits you, he emails you about it with two buttons: Yes opens tailoring for that opening, Not now drops it. It only goes to people who used Remy in the last 14 days. Choose daily, weekly (the default) or off in Account \u2192 Appearance & alerts. Owners see how many get a Yes on the dashboard.", owners: true },
  { id: "2026-11-22-10", date: "2026-11-22", kind: "Changed", title: "Examples before you start", body: "Interview stories, your pitch and My Path now show a short labelled example of what Remy will make, instead of a paragraph. On a phone, each opening has one main button, Tailor resume, with Apply, Keep, Pass and Details on one row under it.", owners: true },
  { id: "2026-11-22-08", date: "2026-11-22", kind: "Changed", title: "A calmer, clearer look", body: "Pages sit on a warm paper background with flatter cards and bigger page titles. Home shows this week\u2019s to-dos and your best openings side by side instead of behind tabs. What\u2019s new is a dot instead of a count, and Remy\u2019s suggested questions are buttons. On a phone, openings start higher on the page.", owners: true },
  { id: "2026-11-22-07", date: "2026-11-22", kind: "Changed", title: "My Path starts with Remy", body: "My Path now opens with Remy checking your direction (\u201cYour resume says finance. Still where you want to go?\u201d) with three quick answers. Future of your field is now a short outlook right there, with the full projections one tap away, instead of its own tab.", owners: true },
  { id: "2026-11-22-06", date: "2026-11-22", kind: "New", title: "Keep or Pass on every opening", body: "Each opening now has Keep and Pass right on the card. Keep saves it and tells Remy you want more like it; Pass hides it and tells Remy the opposite. Changed your mind? Show passed openings and undo.", owners: true },
  { id: "2026-11-22-05", date: "2026-11-22", kind: "New", title: "Interview questions for the job you want", body: "The Interview page now lists the questions the opening you’re applying to is likely to ask, from its own posting, with the line from your resume that answers each one. Practice them out loud right there.", owners: true },
  { id: "2026-11-22-04", date: "2026-11-22", kind: "Changed", title: "LinkedIn moved next to your resume", body: "The LinkedIn tab is gone. A small card beside your resume says what’s on your resume but not on LinkedIn, and opens the full LinkedIn coach when you want it.", owners: true },
  { id: "2026-11-22-03", date: "2026-11-22", kind: "Improved", title: "A clearer ATS check", body: "The ATS check now says plainly what it is: a general check of how common systems like Workday read your file, not the employer’s own system, with sources.", owners: true },
  { id: "2026-11-22-02", date: "2026-11-22", kind: "New", title: "Tailoring writes the draft first", body: "Press Tailor and Remy writes the whole draft from your resume right away, then asks a few optional questions that would make it stronger. Answer, write your own with Other, or skip the rest; your earlier choices on each change are kept.", owners: true },
  { id: "2026-11-22-01", date: "2026-11-22", kind: "New", title: "Your resume in your own file", body: "The colours and fixes now show on your own resume. For a Word file, your changes are written into your file so it keeps your exact design. For a PDF, the colours sit on your real pages until you make a change; upload a Word file to keep your design after edits.", owners: true },
  { id: "2026-11-21-08", date: "2026-11-21", kind: "Improved", title: "Everything beside your resume", body: "Make it stronger, the ATS check and your approved versions and downloads now sit as small cards next to your resume, so the whole page fits on one screen.", owners: true },
  { id: "2026-11-21-07", date: "2026-11-21", kind: "Improved", title: "Fixes right beside your resume", body: "Make it stronger now sits next to your resume instead of below it: open a fix, type the detail, and see it on the page.", owners: true },
  { id: "2026-11-21-06", date: "2026-11-21", kind: "New", title: "Your resume on one page, changed by asking Remy", body: "The Base resume tab is now one page: your resume colour-coded with every problem on its line, Make it stronger, the ATS check and your approved versions and downloads together. To change something, just ask Remy in the chat (\u201cadd Tableau to my skills\u201d); he shows the change first and saves it when you tap Use this.", owners: true },
  { id: "2026-11-21-05", date: "2026-11-21", kind: "Improved", title: "More openings in Austin and Houston", body: "Remy now also reads Q2, GlobalFoundries and Silicon Labs in Austin, and Baker Hughes, Piper Sandler, Axiom Space, Corient and the Chevron and HNTB student career sites in Houston. Each one had entry-level openings in its city when we added it." },
  { id: "2026-11-21-04", date: "2026-11-21", kind: "Changed", title: "A cleaner, calmer Remy", body: "Pages now just say what they are (\u201cOpportunities\u201d, \u201cMy Path\u201d) instead of a slogan. On phones, the first opening shows on your first screen. Remy\u2019s panel opens with a line about the page you\u2019re on, cards are flatter, and labels like \u201cLive\u201d and \u201cYou qualify\u201d read as plain text. From Demetre\u2019s redesign work." },
  { id: "2026-11-21-03", date: "2026-11-21", kind: "Improved", title: "Openings in Austin and Houston", body: "Remy now reads 14 school districts in the Austin and Houston areas (Austin ISD, Leander, Klein, Aldine, Cy-Fair and more) plus Plains All American, Self Financial and Virtu, and reads employers in your own city first. Julio\u2019s job-pool test is what showed Austin and Houston coming up empty." },
  { id: "2026-11-21-02", date: "2026-11-21", kind: "Changed", title: "Design preview: plainer page titles, and job filters that fit on your phone", body: "Each page now just says what it is (\u201cOpportunities\u201d, \u201cMy Path\u201d, \u201cResume & CV\u201d) instead of a slogan. On phones, the job-type filters (All, Jobs, Campus, Events) fit in one row, so openings start higher on the screen. The dark sidebar and menu bar lost their purple tint and match Remy\u2019s black. From Demetre\u2019s redesign work. Owners only for now, while you check it.", owners: true },
  { id: "2026-11-21-01", date: "2026-11-21", kind: "New", title: "See what a job actually involves", body: "In My Path \u2192 Future of your field, tap \u201cWhat\u2019s the job?\u201d under any job to see the tasks the U.S. Department of Labor rates most important for it, in its own words, and for many growing jobs a line from the government\u2019s outlook, with a link to read the rest. No AI writes any of it. Built from Julio\u2019s research for Remy." },
  { id: "2026-11-20-12", date: "2026-11-20", kind: "Fixed", title: "Your feedback stays yours", body: "When the Remy team marks your feedback as handled, their log now keeps only a reference to your note, not your words, so \u201cDelete everything\u201d takes them with it. (The team\u2019s feedback summaries, which can quote a line, are deleted after 30 days.) And if you applied to the beta with your school email but sign in with another address, that application is now in your data download and deleted with your account too." },
  { id: "2026-11-20-11", date: "2026-11-20", kind: "Improved", title: "\u201cDownload my data\u201d now has everything", body: "Accounts \u2192 Account & data \u2192 Download my data now includes everything Remy stores about you: your workspace, the files you uploaded (your resume, photo and feedback screenshots), the feedback you sent, how much you\u2019ve used Remy\u2019s AI, your beta application, and whether Google Calendar is connected. Passwords and sign-in keys are never included." },
  { id: "2026-11-20-10", date: "2026-11-20", kind: "New", title: "Add a screenshot to your feedback", body: "\u201cSend feedback\u201d (in the menu under your name) can now carry a screenshot: tap \u201cAdd a screenshot\u201d, or paste one straight into the box. It\u2019s made smaller before it\u2019s sent, only the Remy team sees it, and it\u2019s deleted with your account." },
  { id: "2026-11-20-09", date: "2026-11-20", kind: "Improved", title: "Clearer LinkedIn and Approved & exports tabs", body: "Adding your LinkedIn (and other profiles) now starts with one Upload PDF button; pasting the text is the backup, with \u201cRead pasted text\u201d once you\u2019ve pasted. Approved & exports points you to tailoring when nothing\u2019s approved yet, and the safety checker\u2019s log is one line (\u201cRemy\u2019s checker stopped 3 overstatements in AI drafts before you saw them\u201d) that opens when you tap it." },
  { id: "2026-11-20-08", date: "2026-11-20", kind: "Improved", title: "Your base resume in three steps too", body: "Resume \u2192 Base resume now walks you through 1) check what Remy read and confirm it, 2) make it stronger (Remy\u2019s suggestions, ATS X-Ray and Evidence passport), 3) your file. New resumes open on step 1; once you\u2019ve confirmed, Remy opens step 2. Once it\u2019s confirmed, steps 2 and 3 just say what\u2019s next instead of showing another \u201cRe-confirm\u201d button." },
  { id: "2026-11-20-07", date: "2026-11-20", kind: "Improved", title: "Tailoring in three clear steps", body: "Tailoring a resume for an opening is now three numbered steps instead of four tabs: 1) review Remy\u2019s changes, one at a time (\u201cUse Remy\u2019s\u201d, \u201cKeep mine\u201d or \u201cEdit\u201d), 2) read your cover letter, 3) approve & download, where every check and the preview sit together above the Approve button. A \u201cNext\u201d button always says what comes next, and changes you already decided fold into one line each (tap one to change your mind)." },
  { id: "2026-11-20-06", date: "2026-11-20", kind: "Improved", title: "My Path: pick a direction and see what it does", body: "Career exploration is lighter: Remy\u2019s suggested directions are short rows showing how many openings there are for that kind of job right now, and the one you tap opens beside them with why it fits, what\u2019s missing and first steps. Pick one and its steps show as on your to-dos or done, and \u201cSee N openings\u201d opens exactly those on Opportunities. Not sure? \u201cNone of these, or not sure yet?\u201d opens the jobs your major leads to, right there instead of in a dropdown at the bottom." },
  { id: "2026-11-20-05", date: "2026-11-20", kind: "Improved", title: "Ask Remy \u201cWhat am I looking at?\u201d on any page", body: "Remy\u2019s chat now knows the exact page and tab you\u2019re on. Ask what it is (or tap \u201cWhat am I looking at?\u201d) and Remy explains that screen with your own openings, resume and applications, and says the one thing worth doing there. It no longer offers to replay the tour; that\u2019s still in the menu under your name as \u201cShow me around again\u201d." },
  { id: "2026-11-20-04", date: "2026-11-20", kind: "Changed", title: "Every check shown in full when you tailor", body: "When you tailor an application, the Checks tab now shows every check right away: the skills the posting names, the unsupported-claim check, the AI second opinion and the file format check. What blocks your approval still comes first. No more \u201cShow all checks\u201d click." },
  { id: "2026-11-20-03", date: "2026-11-20", kind: "Changed", title: "Resume checks always showing, and you can skip the tour", body: "Resume \u2192 Review now shows ATS X-Ray (what an application system reads from your file) and Evidence passport (the proof behind your skills) as regular sections, instead of hidden under \u201cMore checks\u201d. And setup\u2019s last screen has \u201cSkip the tour\u201d next to \u201cEnter my workspace\u201d; you can still take it anytime from \u201cShow me around again\u201d in the menu under your name." },
  { id: "2026-11-20-02", date: "2026-11-20", kind: "Fixed", title: "The tour no longer flickers between pages", body: "When Remy\u2019s tour moved to another page, the screen flashed bright, the highlight slid across from where it was on the last page, and the bubble jumped ahead of it. Now the screen stays dimmed while the next page opens, and the highlight and bubble appear right where they belong." },
  { id: "2026-11-20-01", date: "2026-11-20", kind: "Fixed", title: "No more freezes after you update your resume", body: "After you uploaded or edited your resume, the next visit to Opportunities could make Remy freeze for a few seconds for everyone, because it re-checked every opening against your resume the slow way. That check is now about 10 times faster, so the pause is a fraction of a second instead of several seconds. A resume or posting with the word \u201cconstructor\u201d in it no longer breaks the match scores either." },
  { id: "2026-11-19-20", date: "2026-11-19", kind: "Improved", title: "Every opening says why it's where it is, and your dream employers at a glance", body: "Each card on Opportunities now has a short line built from facts Remy has, like \u201cIn your area \u00b7 Title in your field \u00b7 You show 4 of 6 skills \u00b7 Dream employer\u201d. At the top, your dream employers each show how many openings they have right now (tap one to see them), instead of a \u201cnothing yet\u201d note." },
  { id: "2026-11-19-19", date: "2026-11-19", kind: "New", owners: true, title: "Owners: switch to student view", body: "Your profile menu (More on a phone) has \u201cSwitch to student view\u201d: Career quest, owner notes and the dashboard link hide, so you see Remy exactly as a student does. Switch back the same way. It's saved on your account, so it holds on every device." },
  { id: "2026-11-19-18", date: "2026-11-19", kind: "New", owners: true, title: "Owners only: Career quest, for testing", body: "Owners now see a test version of Career quest: your level, XP and a weekly streak in the left menu, and this week's 3 missions on Home. Missions finish by themselves when you do the real thing (rate openings, save or tailor one, add a person, answer a story question, add a number to a bullet, apply). One mission a week keeps the streak; one missed week is forgiven. Badges only for real wins. Students don't see any of it yet." },
  { id: "2026-11-19-15", date: "2026-11-19", kind: "Improved", title: "Openings in your places come first, and out-of-state ones say why", body: "Opportunities now lists openings in the places you chose first. Below them, under \u201cWorth relocating for\u201d, come openings elsewhere, only if your \u201cOpen to relocating?\u201d answer allows it: \u201cFor the right role\u201d keeps ones whose title is in your field or that are at a dream employer, \u201cYes\u201d keeps them all, \u201cNo\u201d keeps you to your places. Each says why it's there." },
  { id: "2026-11-19-16", date: "2026-11-19", kind: "Changed", title: "Community is for everyone who can help", body: "Community used to open with \u201cComing soon: Alumni connections\u201d, which made it sound like it was only for alumni. It now says what it's for: anyone who can help your career, like a recruiter from a career fair, a professor, a classmate or a manager. Alumni matches from your school are still coming." },
  { id: "2026-11-19-17", date: "2026-11-19", kind: "Changed", title: "Remy asks only when something happened", body: "The weekly \u201cWhat did you do this week?\u201d card and the \u201cQuick question from the Remy team\u201d boxes are gone. Instead, after an interview on your calendar Remy asks how it went with one tap (and adds a thank-you to your to-dos), and after a career fair or event it asks if you met anyone, then opens Community with the event already filled in. The \u201cWas this useful?\u201d thumbs stay." },
  { id: "2026-11-19-13", date: "2026-11-19", kind: "Fixed", title: "\u201cAnywhere in Texas\u201d now means Texas", body: "If you picked \u201cAnywhere in Texas\u201d as a place to look, Remy was reading it as \u201canywhere at all\u201d, so openings in other states ranked just as high as ones near you. Openings in the places you chose now come first, and new searches look there." },
  { id: "2026-11-19-14", date: "2026-11-19", kind: "Changed", title: "The homepage says exactly what Remy does", body: "The front page now says that openings you can't apply to are hidden while ones needing a license or a different major are flagged up front (it used to say you'd never see them), and its feature list names interview stories, the LinkedIn check and networking emails." },
  { id: "2026-11-19-07", date: "2026-11-19", kind: "Fixed", title: "Openings from big employers' career sites show the full posting again", body: "Many openings (from employers whose career sites run on Workday and similar systems, like banks and big tech companies) were coming in with only a title, so Remy said it couldn't read the skills the posting asks for, and tailoring had nothing to work with. Remy now reads the full posting, and openings you already had get their text filled in as Remy checks those employers again. Your saved openings and applications stay as they are." },
  { id: "2026-11-19-08", date: "2026-11-19", kind: "Fixed", title: "The name you go by stays put during setup", body: "On setup's \u201cIs this right?\u201d step, typing what Remy should call you and then answering a question about your resume or LinkedIn used to erase the name before you could save it. It now stays, so Remy greets you, and writes your pitch and letters, with the name you chose." },
  { id: "2026-11-19-10", date: "2026-11-19", kind: "Fixed", title: "Tailoring asks which experience to lead with only when there's a real choice", body: "While tailoring, \u201cWhich experience should your letter lead with?\u201d sometimes offered a single choice labeled with a section heading, like \u201cCERTIFICATIONS: Microsoft Office Specialist\u201d. It now lists only real experiences (a job, club or project, named by your role) and asks only when there are at least two." },
  { id: "2026-11-19-09", date: "2026-11-19", kind: "Improved", title: "Interview stories stay about one experience", body: "When an answer in Interview \u2192 Interview stories sounds like a different experience on your resume (say, your treasurer role typed into a fundraiser story), Remy asks if it's really about that story before saving it. A story that mixes two experiences falls apart when an interviewer asks a follow-up. Say yes and it's saved as you wrote it." },
  { id: "2026-11-19-11", date: "2026-11-19", kind: "Fixed", title: "Networking emails ask for the time you asked for", body: "When you tell Remy you want a 15-minute chat (or half an hour), the email it drafts in Community now asks for exactly that, instead of always asking for 20 to 30 minutes." },
  { id: "2026-11-19-12", date: "2026-11-19", kind: "Fixed", title: "LinkedIn facts in your own words, and a check on your headline", body: "When you add your LinkedIn PDF, Remy no longer turns your listed skills into claims like \u201cProficient in Team Building\u201d: LinkedIn doesn't say how good anyone is, so neither does Remy. And the LinkedIn coach now tells you when your headline names a different field of study than your resume (say \u201cFinance & Accounting\u201d vs \u201cFinance & BIS\u201d) and asks which is right." },
  { id: "2026-11-19-06", date: "2026-11-19", kind: "New", title: "Remy walks you through the whole site", body: "Right after setup, Remy gives you a real tour: page by page he lights up the one thing that matters, says what it's for, and where there's something to do (like saving an opening or opening Details) you do it for real and the tour moves on. Ten short steps, from your next step on Home to openings, tailoring, interview practice, My Path, people you know and your applications. End it anytime, and replay it from \u201cShow me around again\u201d in the menu under your name. The one-line cards on each page are gone." },
  { id: "2026-11-19-05", date: "2026-11-19", kind: "Improved", title: "Paste an interview invite and it's on your calendar", body: "Got an interview invite, an offer or a rejection? Paste the whole email in one box (Progress \u2192 Email updates, or \u201cPaste an interview invite\u201d on Calendar) and Remy reads it right away and shows what it would update. For an interview, Remy fills in the date and time only when the email states them (and shows you the exact words), then puts the interview on your calendar with a prep to-do due that day. Nothing changes until you confirm." },
  { id: "2026-11-19-04", date: "2026-11-19", kind: "Fixed", title: "No more crashes with your browser's translator on", body: "If you use your browser's \u201cTranslate this page\u201d or a page-changing extension, Remy no longer crashes when something on the page updates (a translated line may not refresh until you reload). And when an AI answer comes back cut off, Remy retries it with more room instead of failing." },
  { id: "2026-11-19-03", date: "2026-11-19", kind: "Improved", title: "Shorter opening cards, a lighter My Path, and people you meet at events", body: "Opportunities: each card now shows the title, place, deadline and one line on why it fits; skills, eligibility and gaps open with Details. My Path: the long list of jobs by major sits behind \u201cBrowse jobs by major\u201d, each exam on your field's road is one line you can open, and Future of your field shows the top 3 growing and shrinking jobs for your field first. Community: add where and when you met someone (email is now optional) and Remy adds a reminder to send a short thank-you the next day." },
  { id: "2026-11-19-02", date: "2026-11-19", kind: "New", title: "Remy shows you around, and Interview has its own page", body: "Right after setup, Remy walks you through a first win in three steps: your best opening, the first thing to check on your resume, and when you'll hear from him next. Home's dark card now has a Getting started list (save an opening, confirm your resume, tailor one application, build one interview story, add one person you know) that ticks itself off as you do each one and goes away when you're done. The first time you open each page, Remy says in one sentence what it's for and can point at the one button to press. Interview stories and your pitch now have their own Interview page in the menu; the LinkedIn coach stays under Resume. Want the tour again? \u201cShow me around again\u201d is in the menu under your name." },
  { id: "2026-11-19-01", date: "2026-11-19", kind: "Improved", title: "Interview stories one question at a time, and a calmer Checks tab", body: "Interview: instead of every story with all its empty boxes at once, Remy now asks you one short question at a time in a chat, and your stories sit beside it with how far along each is (\u201c2 of 4\u201d). Open a story to read it, edit your answers, or practice it out loud once it\u2019s ready. Remy also stopped picking course lists like \u201cRelevant coursework\u201d as a story. And when you tailor, the Checks tab now shows only what stops you from approving (or \u201cNothing blocking your approval\u201d), with every detailed report one tap away under \u201cShow all checks\u201d." },
  { id: "2026-11-18-02", date: "2026-11-18", kind: "Improved", title: "Remy asks instead of guessing where you learned a skill", body: "When a posting asks for a skill you list (like Excel) but nothing on your resume shows where it came from, Remy now asks while tailoring: in a class, at a job, or on your own. Your cover letter and pitch then say it your way. Remy no longer writes lines like \u201cthrough my coursework I built Excel skills\u201d or \u201cthat job taught me\u2026\u201d unless you told it so, and the Strongest match card follows the same rule." },
  { id: "2026-11-18-01", date: "2026-11-18", kind: "Improved", title: "Tailoring you can approve, and \u201cDid you apply?\u201d right away", body: "When Remy tailors your resume and finds that one of its own rewrites or your cover letter says more than your resume does (like turning \u201cran the register\u201d into \u201cmanaged\u201d), it now fixes the wording before you see it. If it can\u2019t, it leaves your line as you wrote it and tells you why, so Approve no longer surprises you. After you click Apply on any opening, Remy asks \u201cDid you apply?\u201d right there, and Yes adds it to your tracker. Openings no longer list \u201cMicrosoft Excel\u201d as a gap when your resume says Excel. Smaller fixes: clearer button names in the resume builder, your preferences keep page 1 if you refresh, and the beta terms now say \u201cbeta testers\u201d (you\u2019ll see them once more)." },
  { id: "2026-11-17-02", date: "2026-11-17", kind: "Fixed", title: "Your pitch, your resume file, and answers you tapped", body: "“Draft my pitch” was failing for many students with a short resume: Remy's honesty check mistook everyday words like “I'm” and your school's initials (TCU) for made-up names. It now works, and if Remy ever holds a draft back, it says why instead of asking you to upload a resume you already have. Your downloaded resume no longer prints your graduation date twice or says “Skills: Skills”. And in setup, if you tap one of Remy's suggested answers about a past job (like what you did best there), Remy now treats it as a suggestion: it only uses it after you confirm it's true (Home → Facts to approve), so your plan never claims something you didn't say." },
  { id: "2026-11-17-01", date: "2026-11-17", kind: "Fixed", title: "Openings for students who aren't sure yet", body: "If you told Remy you're not sure what field you want, it was hiding every opening it found. Now only a field you actually chose can hide an opening; what you say you enjoy never does. Picking “Part-time / campus jobs” no longer lets full-time jobs through. Your plan only points you to openings in the places you chose, and says where each one is. And if Remy has nothing from a dream employer you named, Opportunities now says so, with a button to import a posting you found yourself." },
  { id: "2026-11-13-06", date: "2026-11-13", kind: "Improved", title: "A LinkedIn coach that looks at your actual profile", body: "Resume → Interview & LinkedIn → LinkedIn coach now reads more of your LinkedIn PDF: your headline (and suggests a specific one from your own resume if it's generic), your web address (and how to clean it up if it ends in random characters), the 3 top skills recruiters see first (and which resume skills you could pin), and how your About section opens. No About yet? Remy drafts one from your resume for you to edit and paste. Things the PDF can't show, like your photo, are in one short note instead of a checklist line." },
  { id: "2026-11-13-05", date: "2026-11-13", kind: "Improved", title: "Remy reviews your resume, and helps you fix it", body: "Resume → Base resume now opens on Review: Remy's short list of what to fix, each one fixable right there. Missing phone or dates? Type them in. A bullet with no number? Remy asks if you know a real one (like 40 members or $5,000) and drafts the line with it. A line that starts with “Helped with”? Remy asks what you actually did and drafts it from your words. You approve every change, and nothing saves until you press Save. Editing and your file moved to their own tabs (Edit, File & export), so the page is shorter." },
  { id: "2026-11-13-04", date: "2026-11-13", kind: "Improved", title: "A pitch that sounds like you, and practice that helps", body: "Your 30-second pitch is now written to be said out loud: a hello, what you study, one real thing you did, and what you want next, in short everyday sentences with no buzzwords and no question at the end. When you practice out loud (pitch or interview stories), Remy now tells you your pace in words a minute, your filler words, whether you recited it word for word (which can sound memorized), and which names or details you skipped. It all stays in your browser; Remy hears words and timing, not your tone." },
  { id: "2026-11-13-03", date: "2026-11-13", kind: "Improved", title: "Story deck explains itself and asks what's missing", body: "Resume → Interview & LinkedIn → Story deck now explains what a STAR story is (Situation, Task, Action, Result) and why interviewers want one. Every story shows all four parts. Where your resume doesn't say, you get a question about that experience (like “What motivated you to start the club?”) with a box to answer in your own words. Your answers are kept when you rebuild your stories, and Remy can use them elsewhere, like in cover letters." },
  { id: "2026-11-13-02", date: "2026-11-13", kind: "Improved", title: "Remy briefs you before tailoring", body: "When you tailor for an opening, Remy first reads the posting and tells you what the company does, what the role involves, and why you fit, quoting what they ask for next to your own resume line. Then its questions come with answers you can tap, taken from the posting (or type your own). For “Which experience should your letter lead with?”, tap “You pick” and Remy chooses and tells you why. Anything Remy says about a company that isn’t in the posting is marked so you can check it." },
  { id: "2026-11-13-01", date: "2026-11-13", kind: "Fixed", title: "Fixes from the first feedback", body: "When you tailor, answers like “idk” or “I don’t really have one” count as skipped, so they’re never saved as facts about you or used in your letter. If you skip most of Remy’s questions, it tells you the letter will be generic and asks for one real reason first (or type “go” to write it anyway). Evidence Passport now knows “MS Excel” and “Microsoft Excel” are the same skill. Your 30-second pitch no longer ends with a question. LinkedIn coach says plainly that it can’t see your photo instead of asking you to check. Longer feedback notes are now kept in full." },
  { id: "2026-11-09-01", date: "2026-11-09", kind: "Changed", title: "Beta testers, not a “cohort”", body: "The homepage, sign-in, About and Privacy pages and the welcome email now say “beta testers” instead of “Founding Cohort”: apply to be a beta tester, and the team lets people in a group at a time. Nothing else changes: the same form, the same email to sign in with, and your work stays as it is." },
  { id: "2026-11-08-05", date: "2026-11-08", kind: "Improved", title: "The important parts, where you look", body: "Checks (suggestions and what an application system reads from your file) now sit right under your resume file instead of at the very bottom. Openings show your best 10 first, then 10 more at a time. If you haven't picked roles yet or told Remy you're not sure, My Path starts with \"Not sure? Start here\". The approve bar on a tailored draft stays on screen until you approve, and Remy's quick questions appear right after the moment they're about, at the top." },
  { id: "2026-11-08-04", date: "2026-11-08", kind: "New", title: "Tell us what to fix, in a minute", body: "Now and then Remy asks one quick question right after something happens (you confirm your resume, approve a tailored version, or after your first week), and once a week a short check-in on Home asks three questions. Remy's AI may ask one follow-up for an example. The founders read every answer; skip any of it anytime. Your answers are deleted if you delete your account." },
  { id: "2026-11-08-03", date: "2026-11-08", kind: "New", title: "See your edits before you save them", body: "When you edit your base resume and press Save, Remy now shows every change first: what you added, removed or reworded, with the old line crossed out above the new one. Save them or keep editing. (A teammate's idea.)" },
  { id: "2026-11-08-02", date: "2026-11-08", kind: "Improved", title: "Know the rules before you apply", body: "Openings now say plainly when a posting needs a license your resume doesn't show (RN, CPA, CNA, teaching and more) or lists majors that don't include yours, so you can check before spending time on it. Those stay visible. Postings only for U.S. citizens are hidden for students who need visa sponsorship, with the posting's own words." },
  { id: "2026-11-08-01", date: "2026-11-08", kind: "Fixed", title: "Honesty and reliability fixes", body: "A cover letter that says something your resume doesn't show can no longer be approved by accident: fix it, or confirm it's true. \"Strongest match\" only appears when it points to a real line of your resume. Your resume preview no longer gets stuck on \"Drawing your resume\" on slow phones, and where a browser can't show a PDF inside the page, you get a button that opens it instead of a blank box. \"What's it like?\" no longer breaks My Path, Home only shows openings the Openings page would, legal notices in postings aren't read as skills, a pasted email updates the application it names, and dates follow Texas time." },
  { id: "2026-11-07-10", date: "2026-11-07", kind: "Fixed", title: "Remy fits your phone", body: "Every page was checked on phones from the smallest folding-phone screen to an unfolded Fold. Home and Progress to-dos use the full width (the date sits under the title), the openings search has its own row, Skills & certifications reads as a list instead of a squeezed table, resume lines grow to show every word, and a checkbox always stays next to its words. Long emails and links wrap instead of making the page zoom out." },
  { id: "2026-11-07-09", date: "2026-11-07", kind: "Fixed", title: "Owners' dashboard on a phone", body: "On a phone, More → Owners' dashboard now opens it (owners only). The dashboard fits a phone: a slim bar with Back to Remy, the tabs in one row you swipe sideways, the numbers as one short list and filters side by side.", owners: true },
  { id: "2026-11-07-08", date: "2026-11-07", kind: "Changed", title: "Updated privacy, terms and About", body: "The privacy policy now covers the Founding Cohort application, your ratings and feedback, and Remy's automatic problem reports (which page broke and what failed; never your screen or what you type). The beta terms add one line: Remy is invite-only during the beta. Because the terms changed, you'll be asked to agree once more. Delete everything now also removes your feedback, problem reports and Founding Cohort application." },
  { id: "2026-11-07-06", date: "2026-11-07", kind: "Improved", title: "A tidier Account page", body: "Account → Connected sources now lists only what you can actually add: resume, LinkedIn, Handshake, your degree plan, volunteer hours, certificates and transcript (no more “Coming soon” cards), and the import history folds away. The technical AI log on Account & data is folded too." },
  { id: "2026-11-07-07", date: "2026-11-07", kind: "Improved", title: "The menu matches light mode", body: "In light mode, the left menu (and the tab bar on phones) is now a soft gray instead of dark, so the whole app looks like one piece; the page you're on is a white pill. Dark mode is unchanged." },
  { id: "2026-11-07-05", date: "2026-11-07", kind: "Improved", title: "Tell us in one tap, and the homepage is one click away", body: "After a tailored draft and under Remy's coach answers you'll see “Was this useful? 👍 👎”: one tap tells the team what works, and a 👎 can add one line about what was off. Remy also notices on its own when a page breaks or a button doesn't respond, so the team can fix it without you having to report it (no screen recording and nothing you type is sent). The Remy homepage is now in the menu even while you're signed in." },
  { id: "2026-11-07-04", date: "2026-11-07", kind: "Improved", title: "Owners' dashboard, reorganized", body: "The owners' menu is now in three groups: Students (Overview, Beta, Outcomes), Data (Database, Openings, Errors, Agents) and Team. New: the Founding Cohort funnel (applied → accepted → signed in → set up → active this week, by school, year and source), Outcomes (applications that got an answer, interviews, offers, tailored vs not), Database (space used against the free plan, account sizes, each table) and Openings (every posting Remy has found, by industry, career path and company). Counts only, never what a student wrote.", owners: true },
  { id: "2026-11-07-03", date: "2026-11-07", kind: "Improved", title: "Accept sends a welcome email", body: "On Admin → Beta list, Accept now opens a ready-to-send “You're in” email with the student's name and exact sign-in email filled in. Edit it if you like, see exactly what they'll get, then Accept & send: it goes out from the Remy email with a Sign in button. Accepted students have an “Email them” button to send it again.", owners: true },
  { id: "2026-11-07-02", date: "2026-11-07", kind: "New", title: "Founding Cohort applications, live", body: "Admin → Beta list now shows every application from the Founding Cohort form seconds after it's submitted, with what each student wants and where they're stuck. Filter by school, year or who'll give feedback, then Accept (they can sign in right away), move them to the next cohort, or decline. Declined applications can be deleted once a cohort closes.", owners: true },
  { id: "2026-11-07-01", date: "2026-11-07", kind: "Changed", title: "Founding Cohort: invite-only beta", body: "Remy can now run as an invite-only beta. Students apply with the Founding Cohort form; once the team accepts them, they sign in with the same email (Google or a 6-digit email code). Anyone else who tries to sign in sees why and gets the link to apply. Owners manage the accepted list on Admin → Beta list and can email new members “You’re in”.", owners: true },
  { id: "2026-11-06-12", date: "2026-11-06", kind: "Improved", title: "Calmer look, sharper tab icon", body: "The front page, sign-in and Home are calmer: no light beam, no glowing halo around buttons, and the soft orange glows stay still and faint. The browser tab icon is now the Remy fox drawn sharp at any size, without the light square behind it." },
  { id: "2026-11-06-11", date: "2026-11-06", kind: "New", title: "Your answer rate", body: "Progress now shows how many of your applications got an answer, once you have 5 (an automatic “we received your application” doesn’t count; a rejection does). Two new statuses help: “Heard back” when someone writes back, and “No reply” when you stop waiting. A status you change again within 10 minutes counts as a slip, not an answer. Once you have 3 applications with materials approved in Remy and 3 without, it compares them too." },
  { id: "2026-11-06-07", date: "2026-11-06", kind: "Improved", title: "A heads-up before odd names and rude lines", body: "If a name you type looks like a joke, a placeholder, a link or a keyboard mash, Remy points out that it goes on your resume and emails to employers. Resume bullets with language most employers would reject get a red warning on your Resume page and in the editor until you reword them. Remy never blocks you; it just makes sure it’s on purpose." },
  { id: "2026-11-06-08", date: "2026-11-06", kind: "New", title: "Teach Remy what you like", body: "Open an opening’s Details and tap “More like this” or “Not for me”. Your openings re-order right away and each one that moved says why. Say why if you like (the role, the employer, the location, or remote work) and Remy moves openings with the same employer, location or a very similar title too, and checks employers you liked first when it looks for new openings. “Not for me” hides the card; “Show it again” undoes it. Built by Julio on the Remy team." },
  { id: "2026-11-06-09", date: "2026-11-06", kind: "New", title: "Respiratory therapy road, and more sources", body: "Respiratory therapy majors now get their own road: a CoARC-accredited program, the new single NBRC exam from January 2027 (the lower score earns the CRT, the higher the RRT), and the Texas certificate with its jurisprudence exam. Radiography, optometry, OT and nurse practitioner steps now link to ARRT, ASCO, OTCAS and TCU’s nursing catalog, the strength-coach (CSCS) card no longer gives an unconfirmed date, and the exercise physiologist (ACSM) card no longer says you can test in your last semester." },
  { id: "2026-11-06-06", date: "2026-11-06", kind: "Fixed", title: "No name until you choose", body: "While “Which name should Remy use?” is open, Home, the menu, setup, reminder emails and download file names don’t use either name either (not just the coach). Changing your name in Account → Profile, or telling Remy what to call you, answers it and ticks the to-do off. A name that came from connecting LinkedIn is checked the same way as one from Google." },
  { id: "2026-11-06-05", date: "2026-11-06", kind: "New", title: "A road for your health major", body: "My Path → Your field’s road now has its own road for pre-med, pre-PA, pre-pharmacy, pre-dental, pre-vet, pre-optometry, pre-PT, pre-OT, athletic training, speech-language pathology, kinesiology, public health, health administration, radiography and sonography, medical lab science, counseling (LPC), nurse anesthesia and nurse practitioner: the admission test each one really uses (the DAT for dental, not the MCAT), the license after graduate school, and what’s optional. Each exam and license links to the board or testing body it comes from. Plain psychology majors don’t get the counselor license road, since that license needs a master’s." },
  { id: "2026-11-06-04", date: "2026-11-06", kind: "Fixed", title: "Remy asks before using a name", body: "If you sign in with an account under one name and upload a resume with another, Remy no longer assumes the account’s name is yours. You get a to-do, “Which name should Remy use?”; until you answer, Remy’s coach won’t call you by either name and the emails it drafts leave your name for you to fill in. Checks of your LinkedIn and other profiles also say where each fact came from, and never “you said” about something Remy filled in itself." },
  { id: "2026-11-06-03", date: "2026-11-06", kind: "Fixed", title: "Light or dark stays the way you picked it", body: "If you pick light or dark on the home page, Remy keeps it on that device through sign-in and setup (it used to switch back to your device’s setting after you signed in). Pick it in Account → Appearance to use it on every device. The Sign in button at the top no longer hides its text when you point at it in light mode, and the “Create your free account” button stays at its usual brightness. The home page example now has an engineering student too." },
  { id: "2026-11-06-02", date: "2026-11-06", kind: "New", title: "More business roads", body: "My Path → Your field’s road now has its own road for investment banking, financial planning, economics, insurance, energy, sports business, hospitality, sales, entrepreneurship, international business and business information systems, each with what’s required, what’s optional and a source." },
  { id: "2026-11-06-01", date: "2026-11-06", kind: "New", title: "A road for your engineering specialty", body: "My Path → Your field’s road now has its own road for mechanical, electrical, computer, civil, chemical, aerospace, biomedical, industrial, environmental and petroleum engineering: which FE exam fits, how much a PE matters in that specialty (often not at all), useful certifications marked Optional, design teams and internship timing, and the skills entry-level postings list. TCU students pick their emphasis (electrical or mechanical) before their 4th semester." },
  { id: "2026-11-05-09", date: "2026-11-05", kind: "Fixed", title: "Clearer exams and licenses for your field", body: "Your field’s road (My Path) now lists each exam and license with a plain label: Required, Comes with the job, Depends on the job or Optional, plus who actually needs it, why people get it, what you learn and a source. Optional steps are marked Optional (for example, the SIE isn’t needed for finance internships; firms sponsor Series exams after hiring). New roads for marketing, HR, supply chain and management/consulting. Pages also use the full width on big screens, and tabs and buttons are easier to tap on phones." },
  { id: "2026-11-05-08", date: "2026-11-05", kind: "Improved", title: "Same look as the front page", body: "The menu on the left (and the tab bar at the bottom on phones) now has the front page’s dark look with the orange glow, while pages stay light and easy to read (or dark if your device is in dark mode). When you haven’t chatted yet, the Remy panel shows a short welcome and a few questions to start with, instead of an empty space." },
  { id: "2026-11-05-07", date: "2026-11-05", kind: "Improved", title: "Openings fit your phone", body: "On a phone, Openings now shows a job on the first screen: the buttons sit side by side and the categories scroll sideways. Each card shows the company, title, place, due date and why it fits you; tap Details for the skills it asks for, eligibility and gaps. Titles no longer repeat the employer’s name (the full title is under Details), and every button is easier to tap." },
  { id: "2026-11-05-06", date: "2026-11-05", kind: "Improved", title: "More room on laptops, easier taps on phones", body: "On laptops, Remy now shows a little more at once with more room around things, the way it looks on a big monitor. On phones, buttons and tabs are easier to tap and page titles take less room. Home’s next-step card got the front page’s glow, and “Did you apply…?” reads more naturally." },
  { id: "2026-11-05-05", date: "2026-11-05", kind: "Improved", title: "Smoother setup on phones", body: "Setup now says which step you’re on (Step 2 of 6) and matches the new look. Choices are bigger to tap, fields are grouped and you tap a group to open it (the one that matches your major opens by itself), so the page is shorter, “coming soon” connections fit on one line, and examples in text boxes no longer get cut off." },
  { id: "2026-11-05-04", date: "2026-11-05", kind: "Improved", title: "Easier-to-read beta terms", body: "The beta terms you agree to after signing in are the same words, now easier to read: each point has a short label, the list scrolls inside the card so the checkbox and button stay in reach, and a note tells you how many points there are until you reach the last one." },
  { id: "2026-11-05-03", date: "2026-11-05", kind: "Improved", title: "Sign in, phone-friendly", body: "The sign-in page matches the new front page and shows what happens next. On phones, typing your email no longer zooms the page in (this applies to every text box in Remy), your phone can fill in your email, and the buttons are easier to tap." },
  { id: "2026-11-05-02", date: "2026-11-05", kind: "Improved", title: "A livelier front page", body: "The front page is shorter and easier to read on a phone, Remy’s example answers type themselves out, and sections slide in as you scroll (all of it stays still if your device asks for less motion). The “Jump to” buttons and the Beta terms link now go to the right spot, and links to a section of a page (like the beta terms) land on that section, even when opened in a new tab." },
  { id: "2026-11-05-01", date: "2026-11-05", kind: "Fixed", title: "Word downloads keep your design more often", body: "For Word resumes uploaded from today on: if you reword a bullet a lot in Remy, a tailored Word download now changes that line in your own file instead of switching to Remy’s plain layout, and never leaves the old wording next to the new one. A new first bullet goes in above the rest of that job’s bullets. If Remy can’t tell exactly where a line goes, it still says so before you download." },
  { id: "2026-11-03-03", date: "2026-11-03", kind: "Fixed", title: "“Leave out” that works, and what closed while you were away", body: "Things you tell Remy to leave out now match whole words (leaving out “sales” no longer hides Salesforce jobs), also hide postings that require them, and “defense sales roles” works like “defense sales”. Home’s “since you were last here” box now also says when a saved opening closed." },
  { id: "2026-11-03-02", date: "2026-11-03", kind: "Improved", title: "Setup asks what a coach would ask", body: "Setup now also asks (optional, a few taps) what limits what you can take (paid, hours a week, no car), what you’ve tried so far and what worries you most. Your plan’s first step starts from that worry, and Remy repeats your answers back in one line before saving so you can catch anything off." },
  { id: "2026-11-03-01", date: "2026-11-03", kind: "Fixed", title: "Cleaner plan steps", body: "Plan to-dos no longer show Remy’s internal codes (like “j076f2ac1bfaa”), and Home’s next step no longer skips a plan step just because one other posting from that employer didn’t fit you." },
  { id: "2026-11-02-25", date: "2026-11-02", kind: "Improved", title: "A smarter weekly check-in", body: "When your check-in sentence mentions hours (“about 18 hours shadowing”), an application (“applied to Frost Bank”) or an interview, Remy offers to log the hours and update your tracker too. Each one is a checkbox you can untick, and Remy only uses what you actually wrote." },
  { id: "2026-11-02-24", date: "2026-11-02", kind: "Changed", title: "Setup starts with your goal", body: "Setup now opens with one question: what are you working toward? Tap an answer or write your own (“Not sure yet” is fine). Everything Remy suggests starts from it, and you can change it anytime in Account → Profile. Every setup now includes your resume: upload yours, or build one with Remy in about 10 minutes if you don’t have one yet." },
  { id: "2026-11-02-23", date: "2026-11-02", kind: "New", title: "Hours log", body: "Progress → Hours: log volunteering, shadowing, clinical, research or work hours as you go, and see running totals per activity, ready for applications that ask for them." },
  { id: "2026-11-02-22", date: "2026-11-02", kind: "Improved", title: "Chat knows its way around Remy", body: "Ask the chat how to do something (tailor a resume, practice your pitch, import a posting) and it points you to the right page and tab, with a button to go there. It also says plainly what Remy can’t do, like applying for you or seeing Handshake." },
  { id: "2026-11-02-21", date: "2026-11-02", kind: "New", title: "Interview debrief", body: "The day after an interview on your calendar, Home asks how it went. Write what they asked and what you’d do differently while it’s fresh; it’s saved with that application, and Remy can add a thank-you note to your to-dos." },
  { id: "2026-11-02-20", date: "2026-11-02", kind: "Improved", title: "A weekly email worth opening", body: "The weekly digest’s subject now names the best new opening for you (“Frost Bank and 2 more new openings for you”), lists best fits first, and tells you when a saved opening has closed." },
  { id: "2026-11-02-19", date: "2026-11-02", kind: "New", title: "“Did you apply?” and follow-ups", body: "A couple of days after you approve a tailored resume, Home asks whether you applied (one tap updates your tracker). Two weeks after you apply with no news, it suggests a short follow-up and can add it to your to-dos. One question at a time, and “Not yet” or “Not needed” makes it go away." },
  { id: "2026-11-02-18", date: "2026-11-02", kind: "New", title: "Saved openings checked for you", body: "Remy now re-checks the openings you saved or applied to every few days, even when you’re not on the site. If a posting’s page says it’s closed or the link is gone, it shows as Closed, so you don’t spend time on it." },
  { id: "2026-11-02-17", date: "2026-11-02", kind: "Changed", title: "Your resume first", body: "Base resume now opens on your resume itself, ready to edit. Suggestions, what an application system reads from your file, and the evidence behind your skills are in a Checks section below (one click, or the “Checks ↓” link at the top)." },
  { id: "2026-11-02-16", date: "2026-11-02", kind: "Improved", title: "Clearer My Path and Calendar", body: "My Path now opens with the directions Remy built from your resume, with general field exploration below. Calendar’s Upcoming list shows only your next weekly career time, so deadlines and interviews aren’t pushed out." },
  { id: "2026-11-02-15", date: "2026-11-02", kind: "Improved", title: "Home fits your phone", body: "On a phone, your next step and this week’s to-dos now fit on the first screen. The weekly check-in moved below them." },
  { id: "2026-11-02-14", date: "2026-11-02", kind: "Changed", title: "One next step on Home", body: "Home’s “Your next step” now follows your plan: the first plan to-do you haven’t done, so crossing it off moves you on. Remy suggests an opening there only if it passes every filter (your places, eligibility, not hidden, still open). The “Road to an offer” card is gone because it repeated the same thing, and finishing setup now lands on Home. The internship-season card no longer shows for trade, apprenticeship, high school, working or military paths." },
  { id: "2026-11-02-13", date: "2026-11-02", kind: "Changed", title: "Honest about fields Remy doesn't cover yet", body: "Remy reads about 180 employers’ career sites, mostly in business, tech and engineering. If few of them hire in your field (welding, art, nursing and others), Opportunities now says so plainly instead of suggesting you change your filters, and points you to importing postings you find yourself, which Remy checks and tailors your resume to." },
  { id: "2026-11-02-12", date: "2026-11-02", kind: "Fixed", title: "Cleaner postings and skill lists", body: "Postings from school-district job boards no longer show code bits like “document.write” or “&bull;”. Skills written as a group, like “Excel (pivot tables, VLOOKUP)” or “Microsoft Office (Word, Outlook)”, are read as the skills they are instead of being cut at the comma, and one-letter languages like R are kept." },
  { id: "2026-11-02-11", date: "2026-11-02", kind: "Improved", title: "Your field first", body: "Openings whose title names your own field (“Mechanical Design Intern” for mechanical engineering, “Investment Banking Analyst” for investment banking) now come before ones that only fit your broad area, like “Hardware Engineer” or “IT Business Analyst”." },
  { id: "2026-11-02-10", date: "2026-11-02", kind: "Fixed", title: "“Only where I want to work” holds", body: "Remote jobs based abroad (“Remote, St. Petersburg, Russia”, “Remote - EMEA”, “Bengaluru, IN”) no longer show as local. US towns with foreign-sounding names (Paris, TX; Dublin, OH; Albuquerque, New Mexico) are no longer hidden as foreign. Full-time jobs like “Launch Engineer” or “Program Manager” aren’t labelled early-career programs anymore, so they don’t slip in when you chose internships." },
  { id: "2026-11-02-09", date: "2026-11-02", kind: "Improved", title: "New openings while you're away", body: "If you’ve used Remy in the last three weeks, it now checks employers’ sites for you about once a day even when you’re not on the site, so new openings are waiting when you come back. Opportunities shows when Remy last looked and how many are new this week, so you don’t need to press “Find more openings” (it’s still there)." },
  { id: "2026-11-02-08", date: "2026-11-02", kind: "Improved", title: "Remy stays fresh in an open tab", body: "Leave Remy open and come back later: your openings, to-dos and Home update by themselves (after 5 minutes away, or every 15 minutes while it’s open), without touching anything you’re typing. When a new version of Remy ships, a small “Remy was updated. Reload” note appears at the top." },
  { id: "2026-11-02-07", date: "2026-11-02", kind: "Fixed", title: "“You qualify” means you do", body: "Openings say “You qualify” only when the posting states a rule (class year, graduation date) and you meet it. Postings that limit nothing just show their eligibility line. Undergraduate-only roles aren’t offered to trade-school or high-school students, jobs that need a finished degree aren’t shown as fits a year or more before you graduate, and openings hidden because of your own choices say why without claiming you qualify. My Path no longer shows a road from a different field (no MCAT for pre-dental, no electrician licensing for welders). The beta terms now say you’re 16 or older, with a parent or guardian’s OK under 18, so you’ll be asked to agree once more." },
  { id: "2026-11-02-06", date: "2026-11-02", kind: "Fixed", title: "Word downloads on US Letter, and a heads-up first", body: "Remy’s Word files (resume and cover letter) are now US Letter instead of A4, so dates on the right stay inside the margin. If a tailored Word download can’t keep your own design (Remy couldn’t find where a changed line goes in your file), Downloads now tells you before you download, with the line. The “Readable standard font” check now looks at your real font and size instead of always passing." },
  { id: "2026-11-02-05", date: "2026-11-02", kind: "Fixed", title: "Setup understands “not sure” and “nothing”", body: "However you say you don’t know yet (“still deciding”, “TBD”, “I have no idea”, typed on a phone or not), Remy keeps it out of your roles, dream employers and start date. “Nothing comes to mind” or “No thanks” adds nothing to your leave-out list, and “Open to anything” isn’t saved as a company or role. Remy now says “Saving…” until your answer is really saved." },
  { id: "2026-11-02-04", date: "2026-11-02", kind: "Fixed", title: "Honest replies during setup", body: "After each setup question, Remy now says only what really happened to your answer: which part of your profile it went into, or that it’s saved to your AI memory for your plan. No more “they go to the top of my search” when no search runs. Setup also stops asking again about start date, dream employers or things to leave out when you just left them empty, and “I’m not sure” is never saved as a start date or search word." },
  { id: "2026-11-02-03", date: "2026-11-02", kind: "Changed", title: "No more resume score", body: "The 0–100 “ATS readiness” number is gone: it mostly graded writing style, and no employer sees it. Base resume now lists plain suggestions, and each tailored version shows the skills the posting names that are on your resume and the ones worth adding if they’re true. Remy also checks your Word file for tables and text boxes some application systems misread." },
  { id: "2026-11-02-02", date: "2026-11-02", kind: "Fixed", title: "Skills in the posting’s own words", body: "Openings and the tailoring checks now list the skills a posting actually names (Excel, SolidWorks, CPR, Figma), not made-up labels like “Software Skills”. Majors in “pursuing a degree in…” aren’t counted as skills, “you will excel in…” isn’t Excel, and “Python, Java or C++” counts as one choice. More fields covered: engineering, health, design and trades." },
  { id: "2026-11-02-01", date: "2026-11-02", kind: "Fixed", title: "Skill matches you can trust", body: "Remy no longer says you already show a skill because a word starts the same way (“pivot tables” isn’t Tableau, “Aug 2025 – Present” isn’t presentation skills). Related words still count: Shift Manager shows management, team leader shows leadership. Fit notes on saved openings are worked out again." },
  { id: "2026-11-01-13", date: "2026-11-01", kind: "Improved", title: "A calmer Resume page and Home", body: "Resume opens on your resume, with Interview & LinkedIn (stories, pitch, LinkedIn coach) on their own tab. Home puts an upcoming interview first. Change places, dream employers, work authorization or what to leave out anytime in Account → Profile. Cover-letter issues are listed before you approve." },
  { id: "2026-11-01-12", date: "2026-11-01", kind: "Fixed", title: "Fixes from a full student test", body: "Setup's “Looks right” saves what you typed; Arlington, VA no longer counts as Dallas–Fort Worth; the tailoring list follows your places and shows your best 8; your Word download now includes lines you added or reworded in Remy; interview invites are read as interviews; and GPA or major rules aren't listed as skills you lack." },
  { id: "2026-11-01-11", date: "2026-11-01", kind: "Improved", title: "Email sign-in with a code", body: "Continue with Email now sends a 6-digit code from Remy instead of a link, so you can ask on your laptop and type the code from your phone's email. Any email works, not only school email." },
  { id: "2026-11-01-10", date: "2026-11-01", kind: "New", title: "LinkedIn coach", body: "Upload your LinkedIn PDF on the Resume page and Remy lists what's on your resume but missing from LinkedIn, with every field ready to copy, plus a basics checklist. Remy reminds you to re-check once a month." },
  { id: "2026-11-01-08", date: "2026-11-01", kind: "New", title: "Conferences and early programs", body: "Remy now finds conferences in your field each month and lists them with your openings (only ones whose page shows the dates). Discovery days and insight programs are marked as early programs and shown first to first-years and sophomores." },
  { id: "2026-11-01-09", date: "2026-11-01", kind: "New", title: "Practice out loud", body: "Say your pitch or an interview story out loud: Remy times you and, in browsers that can, shows what it heard and your filler words. Nothing is recorded or saved." },
  { id: "2026-11-01-07", date: "2026-11-01", kind: "New", title: "Your field's road", body: "My Path shows the usual steps from college to license in your field (CPA, SIE, FE, NCLEX, LSAT, MCAT and more), with sources. Add this year's steps to your to-dos." },
  { id: "2026-11-01-06", date: "2026-11-01", kind: "Changed", title: "Write your own outreach, with a coach", body: "Network → Write an email: you write it in your own words and Remy gives up to 3 specific comments (a clear small ask, a real connection, length). Recruiters remember students who sound like themselves. “Draft it for me” is still there." },
  { id: "2026-11-01-05", date: "2026-11-01", kind: "New", title: "Your 30-second pitch and the 6-second view", body: "Resume → Base resume: Remy drafts your elevator pitch from your own resume (edit it, then practice out loud with a timer), and the 6-second view shows what a recruiter's eye catches first. Remy also flags mixed date formats." },
  { id: "2026-11-01-04", date: "2026-11-01", kind: "New", title: "Add proof you already have", body: "Account → Connections now takes your GivePulse volunteer record, certificates and unofficial transcript (PDF or pasted text). Remy suggests facts from them, and nothing is used until you approve it." },
  { id: "2026-11-01-03", date: "2026-11-01", kind: "Fixed", title: "Your places stick", body: "If you chose Fort Worth, Home, setup and the weekly email now only show openings there (and remote ones). “Fort Worth, TX” no longer means all of Texas, and “Show all locations” lasts one visit." },
  { id: "2026-11-01-02", date: "2026-11-01", kind: "New", title: "A 30-second weekly check-in", body: "Home asks what you did this week. Tap one (a shift, volunteering, a club, a project, a certificate) and say or type one sentence. Remy turns it into a resume line and LinkedIn fields using only your words; anything you didn't say is left out. You choose what to keep." },
  { id: "2026-11-01-01", date: "2026-11-01", kind: "New", title: "Retention watcher and email numbers", owners: true, body: "Owners: the Agents tab counts students who went quiet and the step most stopped before. Overview shows weekly digests sent and who gets each email, and feedback is counted by page." },
  { id: "2026-10-31-15", date: "2026-10-31", kind: "New", title: "Know your recruiting season", body: "Home shows when internships in your field usually recruit (finance, consulting, tech, engineering, marketing, healthcare, government, nonprofit), so you know whether to apply now or get ready. Dates come from Cornell Career Services’ recruiting timeline and can shift." },
  { id: "2026-10-31-14", date: "2026-10-31", kind: "Improved", title: "Not just four-year college", body: "Tell Remy where you are: community college, trade school, apprenticeship, military, working or high school. Your profile wording and Remy’s advice adapt, including certificates, licenses and roles that don’t need a bachelor’s." },
  { id: "2026-10-31-13", date: "2026-10-31", kind: "New", title: "Remy connects the dots", body: "Saving an opening puts its deadline on your calendar, and Remy can email you 3 days before and on the day. Marking an application “Interview” asks for the date and turns Home into a prep plan. Openings show when you know someone there, contacts show openings at their company, and Home shows what’s new since your last visit. Turn on the weekly digest in Account → Appearance & alerts." },
  { id: "2026-10-31-12", date: "2026-10-31", kind: "Improved", title: "Your real resume, and how employers screen it", body: "Base resume now shows your Word file with its real layout (lines, borders, fonts). Each opening’s Details explain how that employer’s application system (Workday, Greenhouse and others) handles your resume and what to watch for. In My Path, choosing a direction now adds it to your search and puts its first steps on your to-dos; the Academic plan tab is gone (anything you typed there is under Skills)." },
  { id: "2026-10-31-11", date: "2026-10-31", kind: "New", title: "Your weekly career time", body: "Pick one time a week to work on your career (Account → Appearance & alerts, or at the end of setup). It shows on your Remy calendar and can repeat in Google or Apple Calendar. Remy now shows each step while it works on longer jobs, celebrates when you reach a milestone, and Copy buttons show a checkmark." },
  { id: "2026-10-31-09", date: "2026-10-31", kind: "New", title: "Three more agents", body: "Agents tab: the Openings scout checks every employer site Remy reads and flags broken ones, the Researcher answers team questions from the web with numbered sources (Perplexity), and the Marketing drafter writes a LinkedIn post, an Instagram caption and an email to professors for you to edit. Nothing is ever posted or sent for you.", owners: true },
  { id: "2026-10-31-10", date: "2026-10-31", kind: "Improved", title: "Openings from more employers", body: "Remy now waits longer for slow employer career sites (like Travelers and Home Depot), so openings from about 30 more employers show up, and Plaid’s openings are back." },
  { id: "2026-10-31-08", date: "2026-10-31", kind: "New", title: "After a no", body: "When you mark an application Rejected, Remy offers three small steps: ask for one piece of feedback, find two similar openings, and note one thing to try next time. Tap “Not now” to skip it." },
  { id: "2026-10-31-07", date: "2026-10-31", kind: "Improved", title: "Start with what you came for", body: "Setup now asks what would help most today: your resume, openings, an interview, figuring out a direction, or just looking around. Back returns you to the same spot in a list, “Due today” is no longer shown as one day left, and if a change can’t be saved Remy says so with a Retry button." },
  { id: "2026-10-31-06", date: "2026-10-31", kind: "New", title: "Agents tab", body: "Owners' dashboard → Agents: the Feedback & bug sorter groups open errors and feedback into themes with to-dos you can add to the board, and the Weekly analyst sums up the week. Openings scout, Researcher and Marketing drafter are next.", owners: true },
  { id: "2026-10-31-05", date: "2026-10-31", kind: "New", title: "X-Ray, evidence and interview stories", body: "On Resume → Base resume: ATS X-Ray shows what Remy read and lets you add lines it missed, the Evidence passport shows which skills a bullet backs up, and the Story deck builds true interview stories from your resume. An interview on your calendar now turns Home into a 3-step prep plan." },
  { id: "2026-10-31-04", date: "2026-10-31", kind: "New", title: "Your road to an offer", body: "Home now shows six real milestones (resume ready, openings picked, first application, reached out, interview stories, interviewing), each read from what you've actually done, with the next one a tap away." },
  { id: "2026-10-31-03", date: "2026-10-31", kind: "Improved", title: "Openings near you first", body: "If you haven't picked places to work, openings in your own city or state come first. Locations read normally (“Rosemont, IL”), skill tags wrap on phones, and your Opportunities filters stay as you left them." },
  { id: "2026-10-31-02", date: "2026-10-31", kind: "New", title: "Dark mode, your photo, and chat that changes settings", body: "Remy now matches your device's light or dark mode on every page (change it with the screen icon or in Account → Appearance). Add your own profile photo in Account → Profile. Ask Remy to “turn on dark mode” or “stop deadline reminders” and tap to confirm." },
  { id: "2026-10-31-01", date: "2026-10-31", kind: "Fixed", title: "Smoother setup", body: "Setup no longer gets stuck after the last question, start dates are always in the future, and answering a question twice won't repeat your answer." },
  { id: "2026-10-29-08", date: "2026-10-29", kind: "Fixed", title: "Your resume keeps its look", body: "Tailored downloads now keep your font, sizes and margins, including Word files with several bullets per paragraph, monospace fonts and resumes without italics. Honest rewordings like spelling out “RN” are no longer flagged." },
  { id: "2026-10-29-07", date: "2026-10-29", kind: "Improved", title: "Remy learns what you like", body: "Employers you save or apply to come first, ones you keep marking “Not interested” fade out, and “Find more openings” now checks employers it hasn't looked at yet." },
  { id: "2026-10-29-06", date: "2026-10-29", kind: "Improved", title: "More openings that fit you", body: "Remy now reads what a job actually involves, so postings with plain titles like “Summer Intern” show up when the work matches your field. Openings also load faster." },
  { id: "2026-10-29-04", date: "2026-10-29", kind: "Improved", title: "A clearer front page", body: "The front page now shows one thing at a time, with a footer for privacy, beta terms and contact." },
  { id: "2026-10-29-03", date: "2026-10-29", kind: "Changed", title: "Remy is officially in beta", body: "You'll see a Beta label and a one-time agreement. Unfinished features say “Coming soon” so you always know what works today." },
  { id: "2026-10-29-02", date: "2026-10-29", kind: "Changed", title: "Alumni matching is paused", body: "We removed the alumni list until a school gives us permission to use it. Contacts you add yourself still work." },
  { id: "2026-10-29-01", date: "2026-10-29", kind: "Fixed", title: "Word resumes show on Base resume", body: "Your uploaded Word resume appears again, with a Minimize button that Remy remembers." },
  { id: "2026-10-28-01", date: "2026-10-28", kind: "New", title: "One-click tailoring", body: "Tailor your resume for an opening straight from its card, and send us feedback from the menu anytime." },
  { id: "2026-10-29-05", date: "2026-10-29", kind: "Improved", title: "Board, meetings and history", body: "Several teammates per to-do and meeting, instant moves, a north-star number, and finished to-dos move to History after 3 days.", owners: true },
];

/** Items someone hasn't seen: newer than the last id they opened. Owners also see owner-only notes. */
export const unseenNews = (seen: string | undefined, owner = false) =>
  NEWS.filter((n) => (owner || !n.owners) && (!seen || n.id > seen));
export const latestNewsId = () => NEWS.reduce((a, n) => (n.id > a ? n.id : a), "");
